{
  "info": {
    "title": "UAE Product API",
    "description": "UAE Open Finance Product API Specification",
    "version": "v2.1"
  },
  "servers": [
    {
      "url": "https://rs1.[LFICODE].apihub.openfinance.ae/open-finance/product/v2.1"
    },
    {
      "url": "https://rs1.[LFICODE].preprod.apihub.openfinance.ae/open-finance/product/v2.1"
    },
    {
      "url": "https://rs1.altareq1.sandbox.apihub.openfinance.ae/open-finance/product/v2.1"
    }
  ],
  "source_path": "/products",
  "operations": {
    "get": {
      "tags": [
        "Products"
      ],
      "operationId": "GetProducts",
      "summary": "Retrieve Products",
      "description": "Retrieve all Products",
      "parameters": [
        {
          "$ref": "#/components/parameters/Authorization"
        },
        {
          "$ref": "#/components/parameters/x-fapi-customer-ip-address"
        },
        {
          "name": "ProductCategory",
          "in": "query",
          "description": "Filter by product category",
          "required": false,
          "schema": {
            "$ref": "#/components/schemas/AEProductCategoryCodes"
          }
        },
        {
          "name": "IsShariaCompliant",
          "in": "query",
          "description": "Filter by Sharia compliance",
          "required": false,
          "schema": {
            "type": "boolean"
          }
        },
        {
          "name": "LastUpdatedDateTime",
          "in": "query",
          "description": "Filter by last updated date time",
          "required": false,
          "schema": {
            "type": "string",
            "format": "date-time"
          }
        },
        {
          "name": "SortOrder",
          "in": "query",
          "description": "Order of sorting the results",
          "required": false,
          "schema": {
            "type": "string",
            "enum": [
              "asc",
              "desc"
            ],
            "default": "asc"
          }
        },
        {
          "name": "SortField",
          "in": "query",
          "description": "Field to sort the results by",
          "required": false,
          "schema": {
            "type": "string",
            "enum": [
              "LastUpdatedDateTime",
              "ProductId"
            ],
            "default": "LastUpdatedDateTime"
          }
        }
      ],
      "responses": {
        "200": {
          "description": "The request has succeeded.",
          "content": {
            "application/json": {
              "schema": {
                "$ref": "#/components/schemas/ProductResponse"
              }
            }
          }
        },
        "400": {
          "$ref": "#/components/responses/400Error"
        },
        "401": {
          "$ref": "#/components/responses/401Error"
        },
        "403": {
          "$ref": "#/components/responses/403Error"
        },
        "405": {
          "$ref": "#/components/responses/405Error"
        },
        "406": {
          "$ref": "#/components/responses/406Error"
        },
        "415": {
          "$ref": "#/components/responses/415Error"
        },
        "429": {
          "$ref": "#/components/responses/429Error"
        },
        "500": {
          "$ref": "#/components/responses/500Error"
        }
      },
      "security": [
        {
          "TPPOAuth2Security": [
            "products"
          ]
        }
      ]
    }
  }
}

{
  "name": "authorization",
  "in": "header",
  "required": true,
  "description": "An authorization Token as per https://tools.ietf.org/html/rfc6750",
  "schema": {
    "type": "string"
  }
}

{
  "in": "header",
  "name": "x-fapi-customer-ip-address",
  "required": true,
  "description": "The User's IP address if the User is currently logged in with the TPP.",
  "schema": {
    "type": "string"
  }
}

{
  "type": "object",
  "description": "Product Response\n",
  "required": [
    "Data",
    "Links",
    "Meta"
  ],
  "properties": {
    "Data": {
      "description": "Products response\n",
      "type": "array",
      "items": {
        "type": "object",
        "required": [
          "LFIId",
          "LFIBrandId",
          "Products"
        ],
        "properties": {
          "LFIId": {
            "type": "string",
            "description": "The unique identifier for the LFI within the CBUAE ecosystem"
          },
          "LFIBrandId": {
            "type": "string",
            "description": "The unique identifier for the LFI Brand within the CBUAE ecosystem"
          },
          "Products": {
            "type": "array",
            "description": "The Product array can contain one or more products associated to a single LFI",
            "items": {
              "$ref": "#/components/schemas/Product"
            }
          }
        }
      }
    },
    "Links": {
      "$ref": "#/components/schemas/Links"
    },
    "Meta": {
      "$ref": "#/components/schemas/MetaTotalPages"
    }
  }
}

{
  "type": "object",
  "description": "The Product information",
  "required": [
    "ProductId",
    "ProductName",
    "ProductCategory"
  ],
  "properties": {
    "ProductId": {
      "type": "string",
      "description": "A data holder specific unique identifier for this product. This identifier must be unique to a product but does not otherwise need to adhere to ID permanence guidelines."
    },
    "ProductName": {
      "type": "string",
      "description": "The display name of the product.",
      "example": "Savings Account"
    },
    "ProductCategory": {
      "$ref": "#/components/schemas/AEProductCategoryCodes"
    },
    "Description": {
      "description": "A human-readable description of the product that can be displayed to the User for marketing and information purposes.",
      "type": "string"
    },
    "EffectiveFromDateTime": {
      "description": "The date and time from which this product is effective (i.e. is available for origination). Used to enable the articulation of products to the regime before they are available for customers to originate.",
      "type": "string",
      "format": "date-time"
    },
    "EffectiveToDateTime": {
      "description": "The date and time at which this product will be retired and will no longer be offered. Used to enable the managed deprecation of products.",
      "type": "string",
      "format": "date-time"
    },
    "LastUpdatedDateTime": {
      "description": "The last date and time that the information for this product was changed (or the creation date for the product if it has never been altered).",
      "type": "string",
      "format": "date-time"
    },
    "IsShariaCompliant": {
      "type": "boolean",
      "description": "Indicates whether the product is Sharia-compliant."
    },
    "ShariaStructure": {
      "description": "Provides the Islamic finance contract or structure type applied to a product when it has been confirmed as Sharia-compliant.",
      "type": "string",
      "enum": [
        "Ijara",
        "ServiceIjara",
        "Murabaha",
        "Musharaka",
        "Tawarruq"
      ]
    },
    "AlternativeBrandName": {
      "type": "string",
      "description": "If the product is Shari'a Compliant, alternative brand name to sell the product."
    },
    "ShariaInformation": {
      "type": "string",
      "description": "The description of the Sharia compliance information."
    },
    "IsSalaryTransferRequired": {
      "type": "boolean",
      "description": "Does the Consumer need to pay their salary into a current account provided by the LFI to be able to open this product."
    },
    "Links": {
      "$ref": "#/components/schemas/ProductLinks"
    },
    "Eligibility": {
      "$ref": "#/components/schemas/Eligibility"
    },
    "Channels": {
      "type": "array",
      "items": {
        "$ref": "#/components/schemas/Channel"
      }
    },
    "Product": {
      "$ref": "#/components/schemas/ProductDetails"
    },
    "DenominationCurrency": {
      "description": "Denomination currency of product",
      "type": "string",
      "pattern": "^[A-Z]{3}$"
    }
  }
}

{
  "description": "Links to the Product details",
  "type": "object",
  "properties": {
    "ApplicationUri": {
      "description": "A link to apply for the product.",
      "type": "string",
      "format": "uri"
    },
    "ApplicationPhoneNumber": {
      "description": "A phone number to apply for the product.",
      "type": "string"
    },
    "ApplicationEmail": {
      "description": "An email address to apply for the product.",
      "type": "string"
    },
    "ApplicationDescription": {
      "description": "A free text description of the application process for the product, with ways to contact the LFI if applicable.",
      "type": "string"
    },
    "KfsUri": {
      "description": "A link to the Key Facts Statement for the product",
      "type": "string",
      "format": "uri"
    },
    "OverviewUri": {
      "description": "A link to a general overview of the product.",
      "type": "string",
      "format": "uri"
    },
    "TermsUri": {
      "description": "A link to the Terms and conditions for the product.",
      "type": "string",
      "format": "uri"
    },
    "FeesAndPricingUri": {
      "description": "A link to the Fees and Pricing for the product.",
      "type": "string",
      "format": "uri"
    },
    "ScheduleOfChargesUri": {
      "description": "A link to the Schedule of Charges for the product.",
      "type": "string",
      "format": "uri"
    },
    "EligibilityUri": {
      "description": "A link to the Eligibility for the product.",
      "type": "string",
      "format": "uri"
    },
    "CardImageUri": {
      "description": "A link to the Card Image for the product.",
      "type": "string",
      "format": "uri"
    }
  }
}

{
  "type": "object",
  "description": "The eligibility criteria for the product.\n",
  "properties": {
    "ResidenceStatus": {
      "description": "The residence statuses of the User - that are eligible for the product.\n",
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "Type": {
            "$ref": "#/components/schemas/AEProductResidencyStatusCodes"
          },
          "Description": {
            "type": "string",
            "description": "The description of the residence status eligible for the product.\n"
          }
        }
      },
      "example": [
        {
          "Type": "UaeResident",
          "Description": "A person who is a resident of the United Arab Emirates."
        }
      ]
    },
    "EmploymentStatus": {
      "description": "The employment statuses of the User - that are eligible for the product.\n",
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "Type": {
            "type": "string",
            "description": "The type of employment status eligible for the product.\n",
            "enum": [
              "Salaried",
              "NonSalaried",
              "EligibleEmployer",
              "SelfEmployed",
              "Unemployed",
              "MinimumSalary",
              "EmployerEligibility",
              "MinimumEmploymentTenure"
            ]
          },
          "Description": {
            "type": "string",
            "description": "The description of the employment status eligible for the product.\n"
          }
        }
      }
    },
    "CustomerType": {
      "description": "The customer types of the User - that are eligible for the product.\n",
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "Type": {
            "type": "string",
            "description": "The type of customer type eligible for the product.\n",
            "enum": [
              "Retail",
              "SME",
              "Corporate",
              "New",
              "Existing"
            ]
          },
          "Description": {
            "type": "string",
            "description": "The description of the customer type eligible for the product.\n"
          }
        }
      }
    },
    "AccountOwnership": {
      "description": "The account ownership types of the User - that are eligible for the product.\n",
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "Type": {
            "type": "string",
            "description": "The type of account ownership eligible for the product.\n",
            "enum": [
              "Individual",
              "Joint",
              "Multi"
            ]
          },
          "Description": {
            "type": "string",
            "description": "The description of the account ownership eligible for the product.\n"
          }
        }
      }
    },
    "Age": {
      "description": "The age of the User - that are eligible for the product.\n",
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "Type": {
            "type": "string",
            "description": "The type of age eligibility criteria.",
            "enum": [
              "MinimumAge",
              "MaximumAge"
            ]
          },
          "Description": {
            "type": "string",
            "description": "The description of the age eligibility criteria."
          },
          "Value": {
            "type": "number",
            "description": "The value of the age eligibility criteria."
          }
        }
      }
    },
    "FinancialRequirements": {
      "description": "Finance requirements for the product.",
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "properties": {
          "Type": {
            "description": "The type of financial requirement.",
            "type": "string",
            "enum": [
              "MinimumCreditScore",
              "NoRecentDefaults",
              "NoBankruptcyHistory",
              "MaximumDelinquenciesAllowed",
              "MinimumCreditHistoryLength",
              "MinimumDisposableIncome",
              "MinimumSalaryTransferRequirement",
              "MaximumDebtToIncomeRatio",
              "DebtBurdenRatio",
              "Other"
            ]
          },
          "Description": {
            "type": "string",
            "description": "The description of the financial requirement."
          },
          "Value": {
            "description": "The threshold value that the customer must meet or exceed to satisfy the specified financial requirement.",
            "type": "number"
          },
          "Amount": {
            "$ref": "#/components/schemas/AEActiveOrHistoricCurrencyAndAmount_0"
          }
        }
      }
    },
    "AdditionalEligibility": {
      "description": "Additional eligibility criteria for the product.\n",
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "Type": {
            "type": "string",
            "enum": [
              "Student",
              "UaeArmedForces",
              "TimeInCountry",
              "Other"
            ],
            "description": "The type of eligibility criteria."
          },
          "Description": {
            "type": "string",
            "description": "The description of the eligibility criteria."
          }
        }
      }
    }
  }
}

{
  "type": "string",
  "description": "The type of residence status eligible for the product or product requirement.",
  "enum": [
    "UaeResident",
    "ExpatriatesResident",
    "GCCNational",
    "NonUaeResident"
  ]
}

{
  "type": "object",
  "required": [
    "Amount",
    "Currency"
  ],
  "description": "This is the value of the amount in the currency",
  "properties": {
    "Amount": {
      "$ref": "#/components/schemas/AEActiveCurrencyAndAmount_SimpleType"
    },
    "Currency": {
      "$ref": "#/components/schemas/ActiveOrHistoricCurrencyCode_0"
    }
  },
  "additionalProperties": false
}

{
  "description": "A number of monetary units specified in an active currency where the unit of currency is explicit and compliant with ISO 4217.",
  "type": "string",
  "pattern": "^\\d{1,13}$|^\\d{1,13}\\.\\d{1,5}$"
}

{
  "description": "Identification of the currency in which the account is held. A code allocated to a currency under an international currency identification scheme, as described in the latest edition of the international standard ISO 4217 'Codes for the representation of currencies and funds'.",
  "type": "string",
  "pattern": "^[A-Z]{3,3}$",
  "example": "AED"
}

{
  "type": "object",
  "description": "The channels through which the User can use the product.\n",
  "properties": {
    "Type": {
      "type": "string",
      "description": "The type of channel through which the User can use the product.\n",
      "enum": [
        "Phone",
        "Internet",
        "MobileApp",
        "Branch",
        "RelationshipManager",
        "Other"
      ]
    },
    "Description": {
      "type": "string",
      "description": "The description of the channel through which the User can use the product.\n"
    }
  }
}

{
  "type": "object",
  "description": "The product type specific details for the product.\n",
  "properties": {
    "CurrentAccount": {
      "$ref": "#/components/schemas/CurrentAccountDetails"
    },
    "SavingsAccount": {
      "$ref": "#/components/schemas/SavingsDetails"
    },
    "CreditCard": {
      "$ref": "#/components/schemas/CreditCardDetails"
    },
    "Finance": {
      "$ref": "#/components/schemas/FinanceDetails"
    },
    "Mortgage": {
      "$ref": "#/components/schemas/MortgageDetails"
    },
    "DepositRates": {
      "$ref": "#/components/schemas/AEProductDepositRates"
    },
    "FinanceRates": {
      "$ref": "#/components/schemas/AEProductFinanceRates"
    },
    "Tenor": {
      "type": "array",
      "minItems": 1,
      "items": {
        "$ref": "#/components/schemas/AEProductTenorProperties"
      }
    },
    "AssetBacked": {
      "$ref": "#/components/schemas/AEProductAssetBackedProducts"
    },
    "RewardsBenefits": {
      "$ref": "#/components/schemas/AEProductRewardsBenefitsProperties"
    }
  }
}

{
  "type": "object",
  "description": "The details specific to a current account product. When ProductCategory is \"CurrentAccount\" the CurrentAccount object must also be returned\n",
  "properties": {
    "Type": {
      "description": "The type of current account product.\n",
      "type": "string",
      "enum": [
        "Basic",
        "Premium",
        "Advanced",
        "Other"
      ]
    },
    "IsOverdraftAvailable": {
      "type": "boolean",
      "description": "Indicates whether the current account product has an overdraft facility.\n"
    },
    "Documentation": {
      "type": "array",
      "description": "A list of documents that are required by the LFI when applying for the current account product.\n",
      "items": {
        "type": "object",
        "description": "A document that is required by the LFI when applying for the current account product.\n",
        "properties": {
          "Type": {
            "type": "string",
            "description": "The type of document required by the LFI when applying for the current account product.\n",
            "enum": [
              "ApplicationForm",
              "IDCard",
              "Passport",
              "ResidenceVisa",
              "ProofofAddress",
              "UtilityBill",
              "SalaryCertificate",
              "SalarySlip",
              "TradeLicence",
              "BusinessOwnership",
              "Other"
            ]
          },
          "Description": {
            "type": "string",
            "description": "The description of the document required by the LFI when applying for the current account product.\n"
          }
        }
      }
    },
    "Features": {
      "type": "array",
      "description": "A list of features of the current account product.\n",
      "items": {
        "type": "object",
        "description": "A feature of the current account product.\n",
        "properties": {
          "Type": {
            "description": "The type of additional current account feature.\n",
            "type": "string",
            "enum": [
              "IslamicBanking",
              "IslamicFinance",
              "DebitCard",
              "MultipleCurrencies",
              "DigitalWallet",
              "ChequeBook",
              "Cashback",
              "ATMTransfers",
              "FreeCashWithdrawal",
              "FreeInternationalPayments",
              "Contactless",
              "CardlessATMWithdrawal",
              "TellerTransactions",
              "SMSNotifications",
              "BillPayments",
              "FundsTransfer",
              "SalaryAdvance",
              "WorldWideSupport",
              "Other"
            ]
          },
          "Description": {
            "description": "The description of the additional current account feature.\n",
            "type": "string"
          }
        }
      }
    },
    "Charges": {
      "$ref": "#/components/schemas/AEProductCharges"
    },
    "Limits": {
      "type": "array",
      "description": "A list of limits associated with the current account product.",
      "items": {
        "type": "object",
        "description": "A limit of the current account product.",
        "properties": {
          "Type": {
            "type": "string",
            "description": "The type of limit.",
            "enum": [
              "MinimumDeposit",
              "MinimumBalance",
              "MaximumWithdrawal",
              "MaximumCashATMWithdrawal",
              "MaximumInternationalATMWithdrawal",
              "RetailDomesticPurchase",
              "RetailInternationalPurchase",
              "TellerTransactions",
              "Other"
            ]
          },
          "Description": {
            "type": "string",
            "description": "The description of the limit."
          },
          "Amount": {
            "description": "The limit amount",
            "allOf": [
              {
                "$ref": "#/components/schemas/AEActiveOrHistoricCurrencyAndAmount_0"
              }
            ]
          },
          "Value": {
            "type": "number",
            "description": "The value of the limit."
          }
        }
      }
    }
  }
}

{
  "description": "Fees and charges applicable to the account or product",
  "type": "array",
  "minItems": 1,
  "items": {
    "description": "Properties of the charges applied",
    "type": "object",
    "required": [
      "Name",
      "Description",
      "Charge"
    ],
    "properties": {
      "Type": {
        "description": "Type of charge.",
        "type": "string",
        "enum": [
          "MonthlyFees",
          "AnnualFees",
          "BalanceFallBelow",
          "Overdraft",
          "DomesticTransaction",
          "ForeignTransaction",
          "ATMWithdrawal",
          "ChequeBook",
          "ReplacementChequeBook",
          "ReturnCheque",
          "CardReplacement",
          "AccountStatement",
          "LetterIssued",
          "AccountClosure",
          "CashAdvance",
          "LatePayment",
          "BalanceTransfer",
          "OverLimit",
          "SalesVoucherCopy",
          "Processing",
          "FinanceCancellation",
          "PartialPayment",
          "EarlySettlement",
          "FinalSettlement",
          "Other"
        ]
      },
      "Name": {
        "type": "string",
        "description": "Name of the charge",
        "minLength": 1,
        "maxLength": 40
      },
      "Description": {
        "description": "Description of the fee, including purpose and applicability",
        "type": "string"
      },
      "Charge": {
        "description": "Array of charge components including amount, currency, and applicable rate",
        "type": "array",
        "items": {
          "$ref": "#/components/schemas/AEProductFinancialCalculationMeasure"
        }
      },
      "Conditions": {
        "description": "Array of conditions that trigger the fee",
        "type": "array",
        "items": {
          "$ref": "#/components/schemas/AEProductConditions"
        }
      },
      "Justification": {
        "description": "Reasoning or business logic behind the imposition of the fee",
        "type": "string"
      },
      "Frequency": {
        "description": "Frequency or trigger logic for the reward or fee, such as monthly if balance < 1000, or periodic  Hibah distribution",
        "type": "string"
      },
      "DonatedToCharity": {
        "description": "Confirmation if the charge will be donated to charity when the product is Sharia compliant",
        "type": "boolean"
      },
      "Notes": {
        "type": "string",
        "description": "Additional notes or clarifications about the rate structure",
        "minLength": 1,
        "maxLength": 500
      },
      "SupplementaryInformation": {
        "description": "Optional object for supplementary metadata, such as Sharia compliance notes or reward history",
        "type": "object"
      }
    },
    "additionalProperties": false
  }
}

{
  "type": "object",
  "properties": {
    "Amount": {
      "$ref": "#/components/schemas/AEActiveOrHistoricCurrencyAndAmount_0"
    },
    "Rate": {
      "description": "Specifies the percentage rate applied when the charge is calculated as a percentage rather than as a fixed monetary amount.",
      "type": "number",
      "minimum": 0,
      "maximum": 100
    },
    "ApplicationFrequency": {
      "description": "Frequency at which reward, interest, or profit is applied, such as monthly or quarterly,  including Islamic profit distribution",
      "type": "string",
      "enum": [
        "Monthly",
        "Daily"
      ]
    },
    "InterestCalculationMethod": {
      "description": "Method used to calculate interest or profit, such as based on principal or drawdown, including  Islamic calculation methods",
      "type": "string",
      "enum": [
        "PrincipalBalance",
        "OutstandingBalance",
        "InitialDrawdownAmount"
      ]
    },
    "MaximumChargeAmount": {
      "description": "Defines the maximum monetary amount that can be applied when a percentage-based charge calculation would otherwise exceed this limit.",
      "type": "object",
      "required": [
        "Amount",
        "Currency"
      ],
      "properties": {
        "Amount": {
          "$ref": "#/components/schemas/AEActiveCurrencyAndAmount_SimpleType"
        },
        "Currency": {
